content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  touch-action: manipulation;
}

body {
  background-color: #f0f2f5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.calculator-container {
  background-color: #ffffff;
  border-radius: 16px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
  width: 100%;
  max-width: 360px;
  padding: 24px;
  overflow: hidden;
}

.history {
  font-size: 14px;
  color: #8e8e93;
  text-align: right;
  min-height: 20px;
  margin-bottom: 4px;
  word-break: break-all;
}

.display {
  font-size: 36px;
  font-weight: 600;
  color: #1c1c1e;
  text-align: right;
  margin-bottom: 20px;
  word-break: break-all;
  min-height: 44px;
}

.keypad {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.btn {
  background-color: #f2f2f7;
  border: none;
  border-radius: 12px;
  font-size: 18px;
  font-weight: 500;
  color: #1c1c1e;
  height: 56px;
  min-height: 56px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  display: flex;
  justify-content: center;
  align-items: center;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.btn:active {
  transform: scale(0.95);
}

.btn-number {
  background-color: #f9f9fb;
}

.btn-number:hover {
  background-color: #ececee;
}

.btn-operator {
  background-color: #ff9f0a;
  color: #ffffff;
}

.btn-operator:hover {
  background-color: #f59300;
}

.btn-clear {
  background-color: #ff3b30;
  color: #ffffff;
}

.btn-clear:hover {
  background-color: #e0322b;
}

.btn-equal {
  background-color: #34c759;
  color: #ffffff;
  grid-column: span 2;
}

.btn-equal:hover {
  background-color: #2db350;
}

import { useState, useEffect } from 'react';
import './index.css';

export default function App() {
  const [displayValue, setDisplayValue] = useState<string>('0');
  const [historyValue, setHistoryValue] = useState<string>('');
  const [waitingForOperand, setWaitingForOperand] = useState<boolean>(false);
  const [pendingOperator, setPendingOperator] = useState<string | null>(null);
  const [firstOperand, setFirstOperand] = useState<number | null>(null);

  const inputDigit = (digit: string) => {
    if (waitingForOperand) {
      setDisplayValue(digit);
      setWaitingForOperand(false);
    } else {
      setDisplayValue(displayValue === '0' ? digit : displayValue + digit);
    }
  };

  const inputDot = () => {
    if (waitingForOperand) {
      setDisplayValue('0.');
      setWaitingForOperand(false);
      return;
    }
    if (!displayValue.includes('.')) {
      setDisplayValue(displayValue + '.');
    }
  };

  const clearAll = () => {
    setDisplayValue('0');
    setHistoryValue('');
    setFirstOperand(null);
    setPendingOperator(null);
    setWaitingForOperand(false);
  };

  const calculate = (first: number, second: number, op: string): number => {
    switch (op) {
      case '+':
        return first + second;
      case '-':
        return first - second;
      case '*':
        return first * second;
      case '/':
        return second === 0 ? 0 : first / second;
      default:
        return second;
    }
  };

  const performOperation = (nextOperator: string) => {
    const inputValue = parseFloat(displayValue);

    if (firstOperand === null) {
      setFirstOperand(inputValue);
    } else if (pendingOperator) {
      const currentValue = firstOperand;
      const result = calculate(currentValue, inputValue, pendingOperator);

      setFirstOperand(result);
      setDisplayValue(String(result));
    }

    setWaitingForOperand(true);
    setPendingOperator(nextOperator);
    setHistoryValue(`${firstOperand !== null ? firstOperand : inputValue} ${nextOperator}`);
  };

  const handleEqual = () => {
    const inputValue = parseFloat(displayValue);

    if (pendingOperator && firstOperand !== null) {
      const result = calculate(firstOperand, inputValue, pendingOperator);
      setDisplayValue(String(result));
      setHistoryValue(`${firstOperand} ${pendingOperator} ${inputValue} =`);
      setFirstOperand(null);
      setPendingOperator(null);
      setWaitingForOperand(true);
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key >= '0' && e.key <= '9') {
        inputDigit(e.key);
      } else if (e.key === '.') {
        inputDot();
      } else if (e.key === '+') {
        performOperation('+');
      } else if (e.key === '-') {
        performOperation('-');
      } else if (e.key === '*') {
        performOperation('*');
      } else if (e.key === '/') {
        e.preventDefault();
        performOperation('/');
      } else if (e.key === 'Enter' || e.key === '=') {
        handleEqual();
      } else if (e.key === 'Escape') {
        clearAll();
      } else if (e.key === 'Backspace') {
        setDisplayValue((prev) => {
          if (waitingForOperand) return prev;
          return prev.length > 1 ? prev.slice(0, -1) : '0';
        });
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [waitingForOperand, displayValue, firstOperand, pendingOperator]);

  return (
    <div className="calculator-container">
      <div className="history">{historyValue}</div>
      <div className="display">{displayValue}</div>
      <div className="keypad">
        <button className="btn btn-clear" onClick={clearAll}>AC</button>
        <button className="btn btn-operator" onClick={() => performOperation('/')}>÷</button>
        <button className="btn btn-operator" onClick={() => performOperation('*')}>×</button>
        <button className="btn btn-operator" onClick={() => performOperation('-')}>-</button>

        <button className="btn btn-number" onClick={() => inputDigit('7')}>7</button>
        <button className="btn btn-number" onClick={() => inputDigit('8')}>8</button>
        <button className="btn btn-number" onClick={() => inputDigit('9')}>9</button>
        <button className="btn btn-operator" onClick={() => performOperation('+')}>+</button>

        <button className="btn btn-number" onClick={() => inputDigit('4')}>4</button>
        <button className="btn btn-number" onClick={() => inputDigit('5')}>5</button>
        <button className="btn btn-number" onClick={() => inputDigit('6')}>6</button>
        <button className="btn btn-number" onClick={inputDot}>.</button>

        <button className="btn btn-number" onClick={() => inputDigit('1')}>1</button>
        <button className="btn btn-number" onClick={() => inputDigit('2')}>2</button>
        <button className="btn btn-number" onClick={() => inputDigit('3')}>3</button>
        <button className="btn btn-number" onClick={() => inputDigit('0')}>0</button>

        <button className="btn btn-equal" onClick={handleEqual}>=</button>
      </div>
    </div>
  );
}
